(function() {
  const ZENDESK_URL = 'https://support.nzxt.com/api/v2/help_center/articles/search.json';

  function fetchArticles(query, perPage, cb) {
    fetch(ZENDESK_URL + '?query=' + encodeURIComponent(query) + '&locale=en-us&per_page=' + perPage)
      .then(function(r) { return r.json(); })
      .then(function(d) { cb(null, d.results || []); })
      .catch(function(e) { cb(e, []); });
  }

  /* =========================================================
     PREDICTIVE SEARCH MODAL — Tab injection when tabs exist
     ========================================================= */
  (function initModal() {
    var DEBOUNCE_MS = 300;
    var helpPanel = null;
    var lastQuery = '';
    var debounceTimer = null;

    function renderModalArticles(articles) {
      if (!helpPanel) return;
      if (!articles.length) {
        helpPanel.innerHTML = '<p style="padding:16px;color:#888;font-size:13px;">No help articles found.</p>';
        return;
      }
      helpPanel.innerHTML =
        '<div style="padding:16px;" class="v-stack justify-items-start gap-3">' +
          articles.map(function(a) {
            return '<div>' +
              '<a href="' + a.html_url + '" target="_blank" rel="noopener"' +
              ' style="display:block;color:#fff;text-decoration:none;font-size:13px;line-height:1.5;">' +
              '<span style="font-weight:600;">' + a.title + '</span>' +
              '<span style="display:block;font-size:11px;color:#888;margin-top:2px;">' +
                (a.section && a.section.full_path ? a.section.full_path : 'Help Center') +
              '</span>' +
              '</a></div>';
          }).join('') +
          '<div style="margin-top:8px;">' +
            '<a href="https://support.nzxt.com/hc/en-us/search?utf8=%E2%9C%93&query=' + encodeURIComponent(lastQuery) + '"' +
            ' target="_blank" class="button" style="font-size:12px;padding:8px 16px;">View all Help Center results</a>' +
          '</div>' +
        '</div>';
    }

    function injectModal() {
      var xTabs = document.querySelector('x-tabs.predictive-search__tabs');
      var input = document.querySelector('input.header-search__input');
      if (!xTabs || !input || document.getElementById('tab-help-center-modal')) return;

      var newIndex = xTabs.querySelectorAll('button[role="tab"][slot="title"]').length;
      xTabs.style.setProperty('--item-count', newIndex + 1);

      var tabBtn = document.createElement('button');
      tabBtn.type = 'button';
      tabBtn.className = 'h6';
      tabBtn.setAttribute('role', 'tab');
      tabBtn.setAttribute('slot', 'title');
      tabBtn.setAttribute('aria-selected', 'false');
      tabBtn.setAttribute('aria-controls', 'tab-panel-help-center-modal');
      tabBtn.id = 'tab-help-center-modal';
      tabBtn.textContent = 'Help Center';
      xTabs.appendChild(tabBtn);

      helpPanel = document.createElement('div');
      helpPanel.className = 'predictive-search__resource-item';
      helpPanel.setAttribute('role', 'tabpanel');
      helpPanel.setAttribute('slot', 'content');
      helpPanel.setAttribute('hidden', '');
      helpPanel.setAttribute('aria-labelledby', 'tab-help-center-modal');
      helpPanel.id = 'tab-panel-help-center-modal';
      helpPanel.innerHTML = '<p style="padding:16px;color:#888;font-size:13px;">Type to search Help Center...</p>';
      xTabs.appendChild(helpPanel);

      tabBtn.addEventListener('click', function() {
        xTabs.setAttribute('selected-index', newIndex);
        xTabs.style.setProperty('--selected-index', newIndex);
        xTabs.querySelectorAll('[role="tabpanel"][slot="content"]').forEach(function(p) { p.hidden = true; });
        helpPanel.hidden = false;
        xTabs.querySelectorAll('button[role="tab"]').forEach(function(b) { b.setAttribute('aria-selected', 'false'); });
        tabBtn.setAttribute('aria-selected', 'true');
      });

      var q = input.value.trim();
      if (q) {
        lastQuery = q;
        fetchArticles(q, 5, function(e, a) { if (!e) renderModalArticles(a); });
      }

      input.addEventListener('input', function() {
        lastQuery = input.value.trim();
        if (!lastQuery) return;
        clearTimeout(debounceTimer);
        debounceTimer = setTimeout(function() {
          fetchArticles(lastQuery, 5, function(e, a) { if (!e) renderModalArticles(a); });
        }, DEBOUNCE_MS);
      });
    }

    var modalObserver = new MutationObserver(function() {
      var xTabs = document.querySelector('x-tabs.predictive-search__tabs');
      if (!xTabs || xTabs.dataset.helpInjected) return;
      xTabs.dataset.helpInjected = 'true';
      injectModal();
    });
    modalObserver.observe(document.body, { childList: true, subtree: true });
  })();

  /* =========================================================
     PREDICTIVE SEARCH MODAL — No-results fallback
     When Shopify returns zero results, tabs don't render.
     Replace the no-results message with Help Center results.
     ========================================================= */
  (function initModalFallback() {
    var DEBOUNCE_MS = 400;
    var fallbackTimer = null;

    function renderModalFallback(articles, query, container) {
      if (!articles.length) {
        if (!container.querySelector('.hc-fallback-hint')) {
          var hint = document.createElement('div');
          hint.className = 'hc-fallback-hint';
          hint.style.cssText = 'padding:8px 0 0;';
          hint.innerHTML =
            '<a href="https://support.nzxt.com/hc/en-us/search?utf8=%E2%9C%93&query=' + encodeURIComponent(query) + '"' +
            ' target="_blank" rel="noopener" style="color:#8a00fc;font-size:13px;text-decoration:underline;">Search Help Center instead</a>';
          container.appendChild(hint);
        }
        return;
      }

      container.innerHTML =
        '<div class="v-stack justify-items-start gap-3" style="padding:24px 32px;">' +
          '<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;">' +
            '<span style="font-size:11px;text-transform:uppercase;letter-spacing:0.08em;color:#999;font-weight:600;">Help Center Results</span>' +
          '</div>' +
          articles.map(function(a) {
            return '<div>' +
              '<a href="' + a.html_url + '" target="_blank" rel="noopener"' +
              ' style="display:block;color:#fff;text-decoration:none;font-size:13px;line-height:1.5;">' +
              '<span style="font-weight:600;">' + a.title + '</span>' +
              '<span style="display:block;font-size:11px;color:#888;margin-top:2px;">' +
                (a.section && a.section.full_path ? a.section.full_path : 'Help Center') +
              '</span>' +
              '</a></div>';
          }).join('') +
          '<div style="margin-top:8px;">' +
            '<a href="https://support.nzxt.com/hc/en-us/search?utf8=%E2%9C%93&query=' + encodeURIComponent(query) + '"' +
            ' target="_blank" class="button" style="font-size:12px;padding:8px 16px;">View all Help Center results</a>' +
          '</div>' +
        '</div>';
    }

    function checkForNoResults() {
      var predictiveSearch = document.querySelector('predictive-search#header-predictive-search');
      if (!predictiveSearch) return;

      var noResults = predictiveSearch.querySelector('.predictive-search__no-results');
      if (!noResults) return;
      if (noResults.dataset.hcFallbackApplied) return;

      var input = document.querySelector('input.header-search__input');
      var query = input ? input.value.trim() : '';
      if (!query) return;

      noResults.dataset.hcFallbackApplied = 'true';
      var contentDiv = noResults.closest('.predictive-search__content');
      if (!contentDiv) contentDiv = noResults.parentElement;

      fetchArticles(query, 5, function(err, articles) {
        if (err) return;
        renderModalFallback(articles, query, contentDiv);
      });
    }

    var fallbackObserver = new MutationObserver(function() {
      clearTimeout(fallbackTimer);
      fallbackTimer = setTimeout(checkForNoResults, 150);
    });
    fallbackObserver.observe(document.body, { childList: true, subtree: true });

    document.addEventListener('input', function(e) {
      if (!e.target.matches('input.header-search__input')) return;
      var noResults = document.querySelector('.predictive-search__no-results');
      if (noResults) noResults.dataset.hcFallbackApplied = '';
    });
  })();

  /* =========================================================
     FULL SEARCH RESULTS PAGE — Tab injection when tabs exist
     ========================================================= */
  (function initFullPage() {

    function highlightQuery(text, query) {
      if (!text || !query) return text;
      var words = query.split(/\s+/).filter(function(w) { return w.length > 1; });
      if (!words.length) return text;
      var pattern = new RegExp('(' + words.map(function(w) { return w.replace(/[.*+?^${}()|[\]\]/g, '\$&'); }).join('|') + ')', 'gi');
      return text.replace(pattern, '<mark style="background:#facc15;color:#000;padding:1px 3px;border-radius:2px;">$1</mark>');
    }

    function cleanSnippet(snippet, query) {
      if (!snippet) return '';
      var text = snippet.replace(/</?[^>]+(>|$)/g, '').replace(/\s+/g, ' ').trim();
      if (!text) return '';

      var lowerText = text.toLowerCase();
      var queryWords = query.toLowerCase().split(/\s+/).filter(function(w) { return w.length > 1; });
      var matchIndex = -1;

      for (var i = 0; i < queryWords.length; i++) {
        var idx = lowerText.indexOf(queryWords[i]);
        if (idx !== -1 && (matchIndex === -1 || idx < matchIndex)) matchIndex = idx;
      }

      if (matchIndex > 40) {
        var lookback = text.substring(Math.max(0, matchIndex - 60), matchIndex);
        var breakPoint = Math.max(lookback.lastIndexOf('. '), lookback.lastIndexOf('? '), lookback.lastIndexOf('! '));
        if (breakPoint !== -1) {
          text = text.substring(Math.max(0, matchIndex - 60) + breakPoint + 2);
        } else {
          var spaceIdx = text.lastIndexOf(' ', matchIndex - 1);
          text = '...' + text.substring(Math.max(0, spaceIdx));
        }
      }

      if (text.length > 180) {
        var cutoff = text.lastIndexOf(' ', 180);
        text = text.substring(0, cutoff > 120 ? cutoff : 180) + '...';
      }

      return highlightQuery(text, query);
    }

    function renderFullPageCards(articles, query) {
      return '<style>' +
        '.hc-card{text-decoration:none;color:inherit;display:flex;flex-direction:column;padding:28px 24px;border:1px solid rgba(255,255,255,0.08);border-top:3px solid #8a00fc;border-radius:8px;transition:all 0.2s ease;}' +
