      xTabs.appendChild(helpPanel);

      tabBtn.addEventListener('click', function() {
        xTabs.setAttribute('selected-index', newIndex);
        xTabs.style.setProperty('--selected-index', newIndex);
        xTabs.querySelectorAll('[role="tabpanel"][slot="content"]').forEach(function(p) { p.hidden = true; });
