    function injectFullPageFallback() {
      var emptyState = document.querySelector('.empty-state');
      if (!emptyState || emptyState.dataset.hcFallbackApplied) return;
      emptyState.dataset.hcFallbackApplied = 'true';

      var params = new URLSearchParams(window.location.search);
      var query = (params.get('q') || '').trim();
      if (!query) return;

      fetchArticles(query, 10, function(err, articles) {
        if (err || !articles.length) {
          // No help articles either — just add a link below existing content
          var hint = document.createElement('div');
          hint.style.cssText = 'text-align:center;padding:16px 0 0;';
          hint.innerHTML =
            '<a href="https://support.nzxt.com/hc/en-us/search?utf8=%E2%9C%93&query=' + encodeURIComponent(query) + '"' +
            ' target="_blank" rel="noopener" style="color:#8a00fc;font-size:14px;text-decoration:underline;">Search Help Center instead</a>';
          emptyState.appendChild(hint);
          return;
        }

        // Replace the empty state content with Help Center results
        var container = emptyState.closest('.section-stack') || emptyState.parentElement;
        container.innerHTML =
          '<div class="section-header justify-self-center text-center" style="padding-bottom:24px;">' +
            '<div class="v-stack gap-4">' +
              '<h1 class="h2">Search</h1>' +
              '<p>Showing Help Center results for &ldquo;' + query + '&rdquo;</p>' +
            '</div>' +
          '</div>' +
          '<div style="max-width:1200px;margin:0 auto;padding:0 24px;">' +
            renderFullPageCards(articles, query) +
          '</div>';
      });
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', function() {
        injectFullPageTab();
        injectFullPageFallback();
