document.addEventListener('DOMContentLoaded', function() {
  setTimeout(function() {
    const scComparison = document.querySelector('sc-comparison-table');
    if (scComparison && scComparison.shadowRoot) {
      const shadowRoot = scComparison.shadowRoot;

      // 1. Add padding styles
      const style = document.createElement('style');
      style.textContent = `
        .column-group-header .group-name {
          padding-left: 16px;
        }
        th.row-header.sticky-column {
          padding-left: 16px !important;
        }
        .attribute-value ul {
          margin: 0;
          padding-left: 20px;
          list-style-type: disc;
        }
        .attribute-value li {
          margin: 4px 0;
        }
        @media screen and (max-width: 768px) {
          .column-group-header .group-name,
          th.row-header.sticky-column {
            padding-left: 12px !important;
          }
        }
      `;
      shadowRoot.appendChild(style);

      // 2. Convert "and" and comma separated text to bullet lists for I/O rows
      const rows = shadowRoot.querySelectorAll('tr.row--attribute');
      rows.forEach(function(row) {
        const header = row.querySelector('th.row-header');
        if (header) {
          const headerText = header.textContent.trim().toLowerCase();
          // Target Connectivity and I/O rows
          if (headerText.includes('i/o') || headerText.includes('connectivity')) {
            const cells = row.querySelectorAll('.attribute-value');
            cells.forEach(function(cell) {
              const text = cell.textContent.trim();
              if (text.includes(' and ') || text.includes(', ')) {
                // Split by " and " first, then by comma followed by a number
                let items = text.split(' and ').flatMap(part => 
                  part.split(/,\s*(?=\d)/).map(item => item.trim())
                );
                // Remove empty items and trailing commas
                items = items.map(item => item.replace(/,\s*$/, '').trim()).filter(item => item.length > 0);

                const ul = document.createElement('ul');
                items.forEach(function(item) {
                  const li = document.createElement('li');
                  li.textContent = item;
                  ul.appendChild(li);
                });
                cell.textContent = '';
                cell.appendChild(ul);
              }
            });
          }
        }
      });
    }
  }, 1000);
});
(function () {
  if (window.__nzxtWtbTracking) return;
  window.__nzxtWtbTracking = true;

  var KEY = 'nzxt_wtb_attribution';

  function attributionFrom(href) {
    var url;
    try { url = new URL(href, window.location.href); } catch (e) { return null; }
    // Matches every locale (/de-intl/pages/retailers-nzxt) and the legacy
    // /pages/where-to-buy redirect that some older links may still point at.
    if (!/retailers-nzxt|where-to-buy/i.test(url.pathname)) return null;
    // A link that does not leave the current page is not a Where to Buy click. On the
    // retailers page itself every same-page anchor - the skip-to-content link, any
    // in-page jump - resolves to this same pathname and would otherwise fire a phantom
    // event AND overwrite a real attribution in sessionStorage with an empty one.
    if (url.pathname === window.location.pathname) return null;
    return {
      wtb_source: url.searchParams.get('from') || 'unknown',
      wtb_product: url.searchParams.get('product') || ''
    };
  }

  document.addEventListener('click', function (ev) {
    var a = ev.target && ev.target.closest ? ev.target.closest('a[href]') : null;
    if (!a) return;
    var raw = a.getAttribute('href') || '';
    if (!raw || raw.charAt(0) === '#') return;
    var attr = attributionFrom(raw);
    if (!attr) return;

    try { window.sessionStorage.setItem(KEY, JSON.stringify(attr)); } catch (e) {}

    var payload = {
      wtb_source: attr.wtb_source,
      wtb_product: attr.wtb_product,
      wtb_locale: document.documentElement.getAttribute('lang') || ''
    };
    try {
      window.dataLayer = window.dataLayer || [];
      window.dataLayer.push({
        event: 'where_to_buy_click',
        wtb_source: payload.wtb_source,
        wtb_product: payload.wtb_product,
        wtb_locale: payload.wtb_locale
      });
    } catch (e) {}
    try {
      if (typeof window.gtag === 'function') window.gtag('event', 'where_to_buy_click', payload);
    } catch (e) {}
  }, true);
})();
