(function() {
    var WTB_URL = "/pages/retailers-nzxt";
    var WTB_LABEL = "Where to Buy";
    var COMPONENT_TYPES = ['Cases', 'Coolers', 'Fans', 'Power Supplies', 'Motherboards', 'Accessories'];
    var typeCache = {};

    function productType(handle) {
      if (!typeCache[handle]) {
        typeCache[handle] = fetch('/products/' + encodeURIComponent(handle) + '.js')
          .then(function(r) { return r.ok ? r.json() : null; })
          .then(function(p) { return p ? p.type : null; })
          .catch(function() { return null; });
      }
      return typeCache[handle];
    }

    function wtbHref(handle) {
      var joiner = WTB_URL.indexOf('?') === -1 ? '?' : '&';
      return WTB_URL + joiner + 'from=rebuy&product=' + encodeURIComponent(handle);
    }

    function handleFor(block) {
      var link = block.querySelector('a.rebuy-product-title-link, a.rebuy-product-image');
      var match = link && (link.getAttribute('href') || '').match(//products/([^/?#]+)/);
      return match ? decodeURIComponent(match[1]) : null;
    }

    function apply(block) {
      var button = block.querySelector('.rebuy-button');
      var existing = block.querySelector('.nzxt-rebuy-wtb');
      if (!button) return;

      // Back in stock (or a different variant picked): restore Add to Cart.
      if (!button.disabled) {
        if (existing) existing.remove();
        button.style.display = '';
        return;
      }
      if (existing) return;

      var handle = handleFor(block);
      if (!handle) return;

      productType(handle).then(function(type) {
        if (COMPONENT_TYPES.indexOf(type) === -1) return;
        if (!button.disabled || block.querySelector('.nzxt-rebuy-wtb')) return;

        var link = document.createElement('a');
        link.className = 'rebuy-button nzxt-rebuy-wtb';
        link.href = wtbHref(handle);
        link.textContent = WTB_LABEL;
        button.style.display = 'none';
        button.insertAdjacentElement('afterend', link);
      });
    }

    var queued = false;
    function scan() {
      queued = false;
      document.querySelectorAll('.rebuy-widget .rebuy-product-block').forEach(apply);
    }
    function queueScan() {
      if (queued) return;
      queued = true;
      requestAnimationFrame(scan);
    }

    new MutationObserver(queueScan).observe(document.documentElement, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['disabled']
    });
    document.addEventListener('DOMContentLoaded', queueScan);
  })();
